66	func TestLocalRefAcceptsOnlyWhatCanNameAPathOfTheRepository(t *testing.T) {
67		accepted := []string{
68			"base", "../base", "./x.yaml", "v1.2/base", "./github.com/o/r", "a b/c.yaml", "x.yaml", "../../notes/infra.yaml",
69			"overlays/prod", ".", "..",
70		}
71		for _, ref := range accepted {
72			t.Run("accepts "+strconv.Quote(ref), func(t *testing.T) {
73				if ok, reason := localRef(ref); !ok || reason != "" {
74					t.Errorf("localRef(%q) = %v, %q, want true and no reason", ref, ok, reason)
75				}
76			})
77		}
78		refused := []string{
79			"http://127.0.0.1:8080/x.yaml", "https://127.0.0.1/x.yaml", "http://localhost:9/x.yaml", "http://[::1]:9/x.yaml",
80			"http://127.0.0.2:9/x.yaml", "http://x.localhost:9/x.yaml", "HTTP://127.0.0.1/x.yaml",
81			"git@h:o/r", "ssh://h/o/r", "file:///tmp/r", "git::https://h/o/r",
82			"github.com/o/r", "GitHub.com/o/r//s?ref=v1", "GITHUB.COM/o/r", "github.com",
83			"u@h/x", "/abs", "/", `\\srv\s`, `\x`, `C:\x`, "x?ref=1", "x:y",
84			"", "a\x00b", "a\nb", "a\tb", "a\rb", "a\x7fb", "a\x1bb",
85		}
86		for _, ref := range refused {
87			t.Run("refuses "+strconv.Quote(ref), func(t *testing.T) {
88				if ok, reason := localRef(ref); ok || reason == "" {
89					t.Errorf("localRef(%q) = %v, %q, want false and a reason", ref, ok, reason)
90				}
91			})
92		}
