97	func TestReadGateYAMLRefusesWhatItCannotJudge(t *testing.T) {
98		big := "resources: []\n" + strings.Repeat("# padding\n", 100)
99		tests := []struct {
100			name    string
101			content string
102			limit   int64
103		}{
104			{"invalid YAML", "resources: [a\n", 0},
105			{"an anchor", "resources:\n  - &a base\n", 0},
106			{"an alias", "x: &a [base]\nresources: *a\n", 0},
107			{"a merge key", "a: &a {path: p}\npatches:\n  - <<: *a\n", 0},
108			{"a merge key alone", "patches:\n  - <<: {path: p}\n", 0},
109			{"an explicit tag on a value", "resources: !!seq\n  - base\n", 0},
110			{"an explicit tag on a scalar", "resources:\n  - !!str base\n", 0},
111			{"a custom tag", "resources:\n  - !custom base\n", 0},
112			{"a tag on a key", "!!str resources:\n  - base\n", 0},
113			{"a duplicate key", "resources: [a]\nresources: [b]\n", 0},
114			{"a duplicate key, case ignored", "resources: [a]\nResources: [b]\n", 0},
115			{"a duplicate key, upper case", "resources: [a]\nRESOURCES: [b]\n", 0},
116			{"a duplicate key inside an entry", "patches:\n  - path: a\n    path: b\n", 0},
117			{"a duplicate key, case ignored, inside an entry", "patches:\n  - path: a\n    Path: b\n", 0},
118			{"a key that is not ASCII (a Cyrillic e)", "r\u0435sources: [a]\n", 0},
119			{"a key that is not ASCII, quoted", "\"resources\u00a0\": [a]\n", 0},
120			{"a key that is not ASCII, inside an entry", "patches:\n  - p\u0430th: a\n", 0},
121			{"two documents", "resources: [a]\n---\nresources: [b]\n", 0},
122			{"a document after a comment document", "---\nresources: [a]\n---\n# nothing\n---\nresources: [b]\n", 0},
123			{"a sequence at the top", "- resources\n", 0},
124			{"a scalar at the top", "resources\n", 0},
125			{"a file over the limit", big, 100},
126		}
127		for _, tt := range tests {
128			t.Run(tt.name, func(t *testing.T) {
129				file := filepath.Join(t.TempDir(), "kustomization.yaml")
130				writeFile(t, file, tt.content)
131				limit := tt.limit
132				if limit == 0 {
133					limit = 1 << 20
134				}
135	
136				node, reason := readGateYAML(file, limit)
137	
138				if node != nil || reason == "" {
139					t.Errorf("readGateYAML = %v, %q, want no node and a reason", node, reason)
140				}
141			})
142		}
143	}
