212	// vet writes files under a fresh root and asks the gate about overlay (relative to
213	// it). The root is handed over as the temporary directory names it.
214	func vet(t *testing.T, files map[string]string, overlay string, lim gateLimits) gateVerdict {
215		t.Helper()
216		root := writeRepo(t, files)
217		return vetOverlay(t.Context(), root, filepath.Join(root, filepath.FromSlash(overlay)), lim)
218	}
