246	// A reference that is not local, in each field of kustomize 5.8.3 that carries
247	// one, in each of the forms a generator, a transformer or a validator can take,
248	// directly or through a base: the verdict names the file, the field and the value.
249	func TestVetOverlayRefusesANonLocalReferenceInEveryField(t *testing.T) {
250		for _, c := range gateRemoteCases {
251			t.Run(c.name, func(t *testing.T) {
252				got := vet(t, c.files, c.overlayDir(), defaultGateLimits)
253	
254				checkVerdict(t, got, gateRemote, c.file, c.field, c.ref)
255				if got.File != c.file || got.Field != c.field {
256					t.Errorf("File, Field = %q, %q, want exactly %q, %q", got.File, got.Field, c.file, c.field)
257				}
258			})
259		}
260	}
