398	// chain is an overlay d0 that pulls in d1, which pulls in d2, ... n directories.
399	func chain(n int) map[string]string {
400		files := map[string]string{}
401		for i := 0; i < n; i++ {
402			body := "resources:\n  - ok.yaml\n"
403			if i+1 < n {
404				body = fmt.Sprintf("resources:\n  - ../d%d\n", i+1)
405			}
406			files[fmt.Sprintf("d%d/kustomization.yaml", i)] = body
407		}
408		return files
409	}
410	
411	// fan is an overlay that pulls in n distinct bases.
412	func fan(n int) map[string]string {
413		var list strings.Builder
414		files := map[string]string{}
415		for i := 0; i < n; i++ {
416			fmt.Fprintf(&list, "  - ../b%d\n", i)
417			files[fmt.Sprintf("b%d/kustomization.yaml", i)] = "resources:\n  - ok.yaml\n"
418		}
419		files["d0/kustomization.yaml"] = "resources:\n" + list.String()
420		return files
421	}
422	
423	func padded(body string, n int) string {
424		return body + strings.Repeat("#", n) + "\n"
425	}
