14	// DEVDESK-771: how renderKustomizations uses the gate. Everything here goes
15	// through RunKubeconform with a scripted runner and names no symbol of the gate
16	// itself, so these tests run (and fail) before kustomize_gate.go exists.
17	//
18	// The gate runs when kustomize is a native binary, the network is cut
19	// (allow_remote_bases off) and only then. It is asked about each overlay after
20	// scope.cut() and before kustomizeArgs. On a refusal kustomize is not launched
21	// and the finding is K8S-RENDER, HIGH, with no Repro:
22	//   - a reference that is not local: remoteBlockedHeadline, whose Message names
23	//     the file, the field and the reference, each as %q;
24	//   - an overlay that cannot be judged (closed whitelist, fails closed): the
25	//     title and the Steps of its own.
26	
27	const uncheckedTitle = "Overlay not built: its references could not be checked"
28	
29	var nativeKustomize = ToolSpec{Source: ToolSourceBinary, Binary: "kustomize"}
30	
31	// gateRunner answers git (the repository root, or "not a git repository" when
32	// gitRoot is empty), `kustomize build` and kubeconform with a success.
33	func gateRunner(t *testing.T, gitRoot string) *scriptedRunner {
34		t.Helper()
35		r := &scriptedRunner{}
36		r.reply = func(tc toolCmd) ([]byte, error) {
37			if tc.Name == "git" {
38				if len(tc.Args) > 0 && tc.Args[0] == "config" {
39					return nil, &exitError{Code: 1} // core.worktree is not set
40				}
41				if gitRoot == "" {
42					return nil, &exitError{Code: 128, Stderr: "fatal: not a git repository"}
43				}
44				return []byte(gitRoot + "\n"), nil
45			}
46			if subcommandOf(tc) == "build" {
47				return []byte("apiVersion: v1\nkind: ConfigMap\nmetadata:\n  name: built\n"), nil
48			}
49			return []byte(`{"resources":[]}`), nil
50		}
51		useRunner(t, r)
52		return r
53	}
54	
55	func runGate(t *testing.T, target string, kustomize ToolSpec, allowRemote bool) *KubeconformReport {
56		t.Helper()
57		opts := KubeconformOptions{KubernetesVersion: "1.36.0", Kustomize: kustomize, AllowRemoteBases: allowRemote}
58		report, err := RunKubeconform(t.Context(), target, ToolSpec{Source: ToolSourceBinary, Binary: "kubeconform"}, opts, nil)
59		if err != nil {
60			t.Fatalf("RunKubeconform: %v", err)
61		}
62		return report
63	}
64	
65	func renderFindings(report *KubeconformReport) []Finding {
66		var out []Finding
67		for _, f := range report.Findings {
68			if f.ID == K8sRenderID {
69				out = append(out, f)
70			}
71		}
72		return out
73	}
74	
75	func builds(r *scriptedRunner) []toolCmd {
76		return r.callsTo(func(tc toolCmd) bool { return subcommandOf(tc) == "build" })
77	}
78	
79	func gitCalls(r *scriptedRunner) []toolCmd {
80		return r.callsTo(func(tc toolCmd) bool { return tc.Name == "git" })
81	}
