190	func checkUncheckedFinding(t *testing.T, f Finding, dir, file string) {
191		t.Helper()
192		checkRefusalShape(t, f, dir)
193		if f.Title != uncheckedTitle {
194			t.Errorf("Title = %q, want %q", f.Title, uncheckedTitle)
195		}
196		if file != "" && !strings.Contains(f.Message, fmt.Sprintf("%q", file)) {
197			t.Errorf("Message = %q, want it to name the file %q", f.Message, file)
198		}
199		// Dedicated Steps (uncheckedOverlaySteps): not the ones of a build that
200		// failed, not the ones of a blocked remote base, and they name the overlay.
201		for what, other := range map[string][]string{
202			"a failed build":        renderSteps(SourceKustomize, dir, ToolSourceBinary, "boom", false),
203			"a blocked remote base": renderSteps(SourceKustomize, dir, ToolSourceBinary, "", true),
204		} {
205			if slices.Equal(f.Steps, other) {
206				t.Errorf("Steps are the ones of %s: %q", what, f.Steps)
207			}
208		}
209		if !strings.Contains(strings.Join(f.Steps, " "), dir) {
210			t.Errorf("Steps = %q, want them to name the overlay %q", f.Steps, dir)
211		}
212		if f.Resolution == "" || f.Resolution == remoteBlockedResolution || f.Resolution == kustomizeRenderResolution {
213			t.Errorf("Resolution = %q, want one of its own", f.Resolution)
214		}
215	}
