220	func checkVerdict(t *testing.T, got gateVerdict, kind gateKind, file, field, ref string) {
221		t.Helper()
222		if got.Kind != kind {
223			t.Fatalf("verdict = %+v, want kind %v", got, kind)
224		}
225		switch kind {
226		case gateOK:
227			if got.File != "" || got.Field != "" || got.Ref != "" || got.Reason != "" {
228				t.Errorf("verdict = %+v, want nothing but the kind", got)
229			}
230		case gateRemote, gateUnchecked:
231			if got.Reason == "" {
232				t.Errorf("verdict = %+v, want a reason", got)
233			}
234			if file != "" && got.File != file {
235				t.Errorf("File = %q, want %q", got.File, file)
236			}
237			if field != "" && got.Field != field {
238				t.Errorf("Field = %q, want %q", got.Field, field)
239			}
240			if ref != "" && got.Ref != ref {
241				t.Errorf("Ref = %q, want %q", got.Ref, ref)
242			}
243		}
244	}
