432			lim   gateLimits
433			want  gateKind
434		}{
435			{"a chain, default depth", chain(5), defaultGateLimits, gateOK},
436			{"a chain far deeper than the default depth", chain(30), defaultGateLimits, gateUnchecked},
437			{"a chain deeper than a small depth", chain(6), gateLimits{Depth: 2, Visited: 256, FileBytes: 1 << 20, TotalBytes: 1 << 30}, gateUnchecked},
438			{"one level under a small depth", chain(2), gateLimits{Depth: 2, Visited: 256, FileBytes: 1 << 20, TotalBytes: 1 << 30}, gateOK},
439	
440			{"a hundred bases, default", fan(100), defaultGateLimits, gateOK},
441			{"three hundred bases, default", fan(300), defaultGateLimits, gateUnchecked},
442			{"ten bases, a small ceiling", fan(10), gateLimits{Depth: 16, Visited: 3, FileBytes: 1 << 20, TotalBytes: 1 << 30}, gateUnchecked},
443			{"a base named ten times counts once", func() map[string]string {
444				f := fan(1)
445				f["d0/kustomization.yaml"] = "resources:\n" + strings.Repeat("  - ../b0\n", 10)
446				return f
