75	func builds(r *scriptedRunner) []toolCmd {
76		return r.callsTo(func(tc toolCmd) bool { return subcommandOf(tc) == "build" })
77	}
78	
79	func gitCalls(r *scriptedRunner) []toolCmd {
80		return r.callsTo(func(tc toolCmd) bool { return tc.Name == "git" })
81	}
