83	// onlyRenderFinding is the one K8S-RENDER finding of a run in which kustomize
84	// was not launched.
85	func onlyRenderFinding(t *testing.T, r *scriptedRunner, report *KubeconformReport) Finding {
86		t.Helper()
87		if got := builds(r); len(got) != 0 {
88			t.Errorf("kustomize was launched %d time(s), want never: %q", len(got), got)
89		}
90		found := renderFindings(report)
91		if len(found) != 1 {
92			t.Fatalf("%d K8S-RENDER findings, want 1: %+v", len(found), report.Findings)
93		}
94		if len(report.Unrendered) != 0 {
95			t.Errorf("Unrendered = %v: the overlay was refused, not skipped", report.Unrendered)
96		}
97		return found[0]
98	}
