100	func checkRefusalShape(t *testing.T, f Finding, dir string) {
101		t.Helper()
102		if f.ID != K8sRenderID || f.Severity != SeverityHigh || f.Source != SourceKustomize || f.IaCType != "kustomize" {
103			t.Errorf("finding = %s %s %s %s: a refusal is a K8S-RENDER finding, HIGH, from kustomize", f.ID, f.Severity, f.Source, f.IaCType)
104		}
105		if want := dir + "/kustomization.yaml"; f.File != want {
106			t.Errorf("File = %q, want the overlay's own %q", f.File, want)
107		}
108		// A copied `kustomize build` would run what the gate refused to run.
109		if f.Repro != "" {
110			t.Errorf("Repro = %q, want none", f.Repro)
111		}
112		if len(f.Steps) == 0 || len(stepProblems(f.Steps)) > 0 {
113			t.Errorf("Steps = %q (%v), want steps that follow the convention", f.Steps, stepProblems(f.Steps))
114		}
115	}
