299	// kubeconformStdinArgs validates what arrives on stdin. A container gets -i
300	// and no repository mount: it reads nothing but its input and its cache.
301	func kubeconformStdinArgs(rendered []byte, tool ToolSpec, opts KubeconformOptions) toolCmd {
302		flags := kubeconformFlags(tool, opts)
303		if tool.Source != ToolSourceContainer {
304			return toolCmd{Name: kubeconformBinary(tool), Args: append(flags, "-"), Stdin: rendered}
305		}
306		engineArgs := []string{"-i"}
307		if opts.CacheDir != "" {
308			engineArgs = append(engineArgs, "-v", opts.CacheDir+":"+kubeconformCacheMount)
309		}
310		return containerRun{
311			Flags: engineArgs, Image: kubeconformImage(tool.Image), Argv: append(flags, "-"), Stdin: rendered,
312		}.cmd()
313	}
